"""CRUD operations for the metadata database."""

import json
from collections.abc import Sequence

from sqlalchemy import select, func
from sqlalchemy.orm import Session

from backend.db.models import Idea, Paper, PipelineRun, Proposal, ResearchGapDB

# --- Papers ---


def create_paper(session: Session, **kwargs) -> Paper:
    paper = Paper(**kwargs)
    session.add(paper)
    session.commit()
    session.refresh(paper)
    return paper


def get_paper(session: Session, paper_id: int) -> Paper | None:
    return session.get(Paper, paper_id)


def get_paper_by_source_id(session: Session, source_id: str) -> Paper | None:
    return session.execute(select(Paper).where(Paper.source_id == source_id)).scalar_one_or_none()


def list_papers(session: Session, limit: int = 50, offset: int = 0) -> Sequence[Paper]:
    return (
        session.execute(select(Paper).order_by(Paper.id.desc()).limit(limit).offset(offset))
        .scalars()
        .all()
    )


# --- Ideas ---


def create_idea(session: Session, **kwargs) -> Idea:
    idea = Idea(**kwargs)
    session.add(idea)
    session.commit()
    session.refresh(idea)
    return idea


def get_idea(session: Session, idea_id: int) -> Idea | None:
    return session.get(Idea, idea_id)


def count_ideas(
    session: Session,
    domain: str | None = None,
    min_score: float | None = None,
) -> int:
    stmt = select(func.count()).select_from(Idea)
    if domain is not None:
        stmt = stmt.where(Idea.domain == domain)
    if min_score is not None:
        stmt = stmt.where(Idea.overall_score >= min_score)
    return session.execute(stmt).scalar_one()


def list_ideas(
    session: Session,
    limit: int = 50,
    offset: int = 0,
    domain: str | None = None,
    min_score: float | None = None,
) -> Sequence[Idea]:
    stmt = select(Idea).order_by(Idea.id.desc())
    if domain is not None:
        stmt = stmt.where(Idea.domain == domain)
    if min_score is not None:
        stmt = stmt.where(Idea.overall_score >= min_score)
    stmt = stmt.limit(limit).offset(offset)
    return session.execute(stmt).scalars().all()


def update_idea_scores(
    session: Session,
    idea_id: int,
    novelty_score: float | None = None,
    feasibility_score: float | None = None,
    novelty_report: str | None = None,
    feasibility_report: str | None = None,
) -> Idea | None:
    idea = session.get(Idea, idea_id)
    if not idea:
        return None
    if novelty_score is not None:
        idea.novelty_score = novelty_score
    if feasibility_score is not None:
        idea.feasibility_score = feasibility_score
    if novelty_report is not None:
        idea.novelty_report = novelty_report
    if feasibility_report is not None:
        idea.feasibility_report = feasibility_report
    if idea.novelty_score is not None and idea.feasibility_score is not None:
        normalized_feasibility = idea.feasibility_score / 10.0
        idea.overall_score = (idea.novelty_score + normalized_feasibility) / 2
    session.commit()
    session.refresh(idea)
    return idea


def update_idea_feedback(
    session: Session,
    idea_id: int,
    rating: int,
    notes: str | None = None,
) -> Idea | None:
    idea = session.get(Idea, idea_id)
    if not idea:
        return None
    idea.user_rating = rating
    idea.user_notes = notes
    session.commit()
    session.refresh(idea)
    return idea


# --- Proposals ---


def create_proposal(session: Session, idea_id: int, content_md: str, **kwargs) -> Proposal:
    proposal = Proposal(idea_id=idea_id, content_md=content_md, **kwargs)
    session.add(proposal)
    session.commit()
    session.refresh(proposal)
    return proposal


def get_proposal_by_idea(session: Session, idea_id: int) -> Proposal | None:
    return session.execute(select(Proposal).where(Proposal.idea_id == idea_id)).scalar_one_or_none()


# --- Pipeline Runs ---


def count_pipeline_runs(session: Session) -> int:
    return session.execute(select(func.count()).select_from(PipelineRun)).scalar_one()


def list_pipeline_runs(
    session: Session,
    limit: int = 20,
    offset: int = 0,
) -> Sequence[PipelineRun]:
    return (
        session.execute(
            select(PipelineRun).order_by(PipelineRun.id.desc()).limit(limit).offset(offset)
        )
        .scalars()
        .all()
    )


def create_pipeline_run(session: Session, **kwargs) -> PipelineRun:
    run = PipelineRun(**kwargs)
    session.add(run)
    session.commit()
    session.refresh(run)
    return run


def get_pipeline_run(session: Session, run_id: int) -> PipelineRun | None:
    return session.get(PipelineRun, run_id)


def update_pipeline_run(
    session: Session,
    run_id: int,
    status: str | None = None,
    current_stage: str | None = None,
    error_message: str | None = None,
) -> PipelineRun | None:
    run = session.get(PipelineRun, run_id)
    if not run:
        return None
    if status is not None:
        run.status = status
    if current_stage is not None:
        run.current_stage = current_stage
        completed = json.loads(run.stages_completed)
        if current_stage not in completed:
            completed.append(current_stage)
            run.stages_completed = json.dumps(completed)
    if error_message is not None:
        run.error_message = error_message
    from datetime import datetime, timezone

    if status == "completed":
        run.completed_at = datetime.now(timezone.utc)
    session.commit()
    session.refresh(run)
    return run


# --- Research Gaps ---


def create_gap(session: Session, **kwargs) -> ResearchGapDB:
    gap = ResearchGapDB(**kwargs)
    session.add(gap)
    session.commit()
    session.refresh(gap)
    return gap


def get_gap(session: Session, gap_id: int) -> ResearchGapDB | None:
    return session.get(ResearchGapDB, gap_id)


def list_gaps_by_run(session: Session, run_id: int) -> Sequence[ResearchGapDB]:
    return (
        session.execute(
            select(ResearchGapDB)
            .where(ResearchGapDB.pipeline_run_id == run_id)
            .order_by(ResearchGapDB.confidence.desc())
        )
        .scalars()
        .all()
    )


def count_gaps_by_run(session: Session, run_id: int) -> int:
    return session.execute(
        select(func.count())
        .select_from(ResearchGapDB)
        .where(ResearchGapDB.pipeline_run_id == run_id)
    ).scalar_one()

import { useState } from "react";
import { RunConfigForm } from "@/components/pipeline/run-config-form";
import { AutonomousForm } from "@/components/pipeline/autonomous-form";
import { StageProgress } from "@/components/pipeline/stage-progress";
import { usePipelineProgress } from "@/hooks/usePipelineProgress";
import { triggerRun } from "@/api/pipeline";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import type { PipelineRunRequest } from "@/api/types";
import { CheckCircle2 } from "lucide-react";

export default function PipelineNew() {
  const [runId, setRunId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { stages, isComplete, isConnected } = usePipelineProgress(runId);

  async function handleStart(config: PipelineRunRequest) {
    setIsLoading(true);
    setError(null);
    try {
      const res = await triggerRun(config);
      setRunId(res.run_id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to start pipeline");
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Pipeline</h1>
        <p className="text-muted-foreground">Configure and launch a research pipeline.</p>
      </div>

      {!runId && (
        <Tabs defaultValue="single">
          <TabsList>
            <TabsTrigger value="single">Single Run</TabsTrigger>
            <TabsTrigger value="autonomous">Autonomous Cycle</TabsTrigger>
          </TabsList>
          <TabsContent value="single">
            <RunConfigForm onSubmit={handleStart} isLoading={isLoading} />
          </TabsContent>
          <TabsContent value="autonomous">
            <AutonomousForm onCycleStarted={setRunId} />
          </TabsContent>
        </Tabs>
      )}

      {error && (
        <Card className="border-destructive">
          <CardContent className="p-4 text-sm text-destructive">{error}</CardContent>
        </Card>
      )}

      {runId && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg">Pipeline Progress</CardTitle>
              <div className="flex items-center gap-2">
                <Badge variant="outline">Run #{runId}</Badge>
                {isComplete ? (
                  <Badge className="bg-green-100 text-green-800">Complete</Badge>
                ) : isConnected ? (
                  <Badge className="bg-blue-100 text-blue-800">Live</Badge>
                ) : (
                  <Badge variant="secondary">Connecting...</Badge>
                )}
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <StageProgress stages={stages} currentStage={null} />
          </CardContent>

          {isComplete && (
            <CardContent className="border-t pt-4">
              <div className="flex items-center gap-2 text-green-700">
                <CheckCircle2 className="h-5 w-5" />
                <span className="font-medium">Pipeline completed successfully</span>
              </div>
            </CardContent>
          )}
        </Card>
      )}
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { lazy, Suspense } from "react";
import { listRuns } from "@/api/pipeline";
import { getSystemStatus } from "@/api/status";
import { listIdeas } from "@/api/ideas";
import { RunCard } from "@/components/pipeline/run-card";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useNavigate } from "react-router-dom";
import { Activity, Lightbulb, FlaskConical, Server } from "lucide-react";

const ScoreDistributionChart = lazy(() =>
  import("@/components/charts/score-distribution").then((m) => ({ default: m.ScoreDistributionChart })),
);
const DomainBreakdownChart = lazy(() =>
  import("@/components/charts/domain-breakdown").then((m) => ({ default: m.DomainBreakdownChart })),
);
const RunStatusChart = lazy(() =>
  import("@/components/charts/run-status-chart").then((m) => ({ default: m.RunStatusChart })),
);

export default function Dashboard() {
  const navigate = useNavigate();

  const { data: status, isLoading: statusLoading } = useQuery({
    queryKey: ["status"],
    queryFn: getSystemStatus,
  });

  const { data: runsData, isLoading: runsLoading } = useQuery({
    queryKey: ["runs", { limit: 5 }],
    queryFn: () => listRuns({ limit: 5 }),
  });

  const { data: ideasData, isLoading: ideasLoading } = useQuery({
    queryKey: ["ideas", { limit: 5 }],
    queryFn: () => listIdeas({ limit: 5 }),
  });

  const { data: chartIdeas } = useQuery({
    queryKey: ["ideas", { limit: 200 }],
    queryFn: () => listIdeas({ limit: 200 }),
  });

  const { data: chartRuns } = useQuery({
    queryKey: ["runs", { limit: 50 }],
    queryFn: () => listRuns({ limit: 50 }),
  });

  const hasChartData =
    (chartIdeas?.ideas.length ?? 0) > 0 || (chartRuns?.runs.length ?? 0) > 0;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground">Overview of your research pipeline.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Runs</CardTitle>
            <Activity className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {runsLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{runsData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Ideas</CardTitle>
            <Lightbulb className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {ideasLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{ideasData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">System</CardTitle>
            <Server className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {statusLoading ? (
              <Skeleton className="h-8 w-24" />
            ) : (
              <div>
                <span className="text-2xl font-bold">{status?.app_name ?? "—"}</span>
                <p className="text-xs text-muted-foreground">v{status?.version ?? "—"}</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {hasChartData && (
        <Suspense fallback={<Skeleton className="h-64 w-full" />}>
          <div className="space-y-4">
            <h2 className="text-lg font-semibold">Analytics</h2>
            <div className="grid gap-4 md:grid-cols-2">
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Score Distribution</CardTitle>
                </CardHeader>
                <CardContent>
                  <ScoreDistributionChart ideas={chartIdeas?.ideas ?? []} />
                </CardContent>
              </Card>
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Run Status</CardTitle>
                </CardHeader>
                <CardContent>
                  <RunStatusChart runs={chartRuns?.runs ?? []} />
                </CardContent>
              </Card>
            </div>
            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">Ideas by Domain</CardTitle>
              </CardHeader>
              <CardContent>
                <DomainBreakdownChart ideas={chartIdeas?.ideas ?? []} />
              </CardContent>
            </Card>
          </div>
        </Suspense>
      )}

      <div className="grid gap-6 md:grid-cols-2">
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold">Recent Runs</h2>
            <button
              onClick={() => navigate("/pipeline/new")}
              className="text-sm text-primary hover:underline"
            >
              New run
            </button>
          </div>
          {runsLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
              ))}
            </div>
          ) : runsData?.runs.length ? (
            runsData.runs.map((run) => <RunCard key={run.id} run={run} />)
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <FlaskConical className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No runs yet. Start your first pipeline!</p>
              </CardContent>
            </Card>
          )}
        </div>

        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold">Recent Ideas</h2>
            <button
              onClick={() => navigate("/ideas")}
              className="text-sm text-primary hover:underline"
            >
              View all
            </button>
          </div>
          {ideasLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
              ))}
            </div>
          ) : ideasData?.ideas.length ? (
            ideasData.ideas.map((idea) => (
              <Card
                key={idea.id}
                className="cursor-pointer hover:bg-accent/50 transition-colors"
                onClick={() => navigate(`/ideas/${idea.id}`)}
              >
                <CardContent className="p-4">
                  <p className="text-sm font-medium line-clamp-1">{idea.title}</p>
                  <p className="text-xs text-muted-foreground">{idea.domain}</p>
                </CardContent>
              </Card>
            ))
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <Lightbulb className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No ideas generated yet.</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import type { PipelineRunSummary } from "@/api/types";
import { cn } from "@/lib/utils";

interface RunCardProps {
  run: PipelineRunSummary;
  onClick?: () => void;
}

const statusColors: Record<string, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  running: "bg-blue-100 text-blue-800",
  completed: "bg-green-100 text-green-800",
  failed: "bg-red-100 text-red-800",
};

export function RunCard({ run, onClick }: RunCardProps) {
  return (
    <Card
      className={cn("cursor-pointer transition-colors hover:bg-accent/50", onClick && "cursor-pointer")}
      onClick={onClick}
    >
      <CardContent className="flex items-center justify-between p-4">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium">Run #{run.id}</span>
            <Badge className={cn("text-xs", statusColors[run.status])} variant="secondary">
              {run.status}
            </Badge>
          </div>
          <p className="text-xs text-muted-foreground mt-1">{run.domain}</p>
        </div>
        <div className="text-right flex-shrink-0 ml-4">
          {run.ideas_count > 0 && (
            <span className="text-sm font-medium">{run.ideas_count} ideas</span>
          )}
          <p className="text-xs text-muted-foreground">
            {new Date(run.created_at).toLocaleDateString()}
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

import { apiFetch } from "./client";
import type {
  PipelineRunRequest,
  PipelineRunSummary,
  PipelineRunDetail,
  TriggerRunResponse,
  AutonomousCycleRequest,
  AutonomousCycleResponse,
} from "./types";

export function triggerRun(req: PipelineRunRequest): Promise<TriggerRunResponse> {
  return apiFetch("/pipeline/run", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export function listRuns(params?: {
  limit?: number;
  offset?: number;
}): Promise<{ runs: PipelineRunSummary[]; total: number }> {
  const search = new URLSearchParams();
  if (params?.limit) search.set("limit", String(params.limit));
  if (params?.offset) search.set("offset", String(params.offset));
  const qs = search.toString();
  return apiFetch(`/pipeline/runs${qs ? `?${qs}` : ""}`);
}

export function getRunDetail(id: number): Promise<PipelineRunDetail> {
  return apiFetch(`/pipeline/runs/detail/${id}`);
}

export function cancelRun(runId: string): Promise<{ status: string; run_id: string }> {
  return apiFetch(`/pipeline/runs/${runId}`, { method: "DELETE" });
}

export function triggerAutonomous(req: AutonomousCycleRequest): Promise<AutonomousCycleResponse> {
  return apiFetch("/pipeline/autonomous", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

// --- Pipeline ---

export interface PipelineRunRequest {
  domain?: string;
  max_gaps?: number;
  generation_rounds?: number | null;
  ideas_per_round?: number | null;
  search_queries?: string[] | null;
  run_novelty?: boolean;
  run_feasibility?: boolean;
  run_synthesis?: boolean;
  export_format?: string;
}

export interface PipelineRunSummary {
  id: number;
  status: "pending" | "running" | "completed" | "failed";
  domain: string;
  current_stage: string | null;
  ideas_count: number;
  created_at: string;
  completed_at: string | null;
  error_message: string | null;
}

export interface PipelineRunDetail extends PipelineRunSummary {
  config: Record<string, unknown>;
  stages_completed: string[];
  ideas: IdeaSummary[];
}

export interface TriggerRunResponse {
  run_id: string;
  status: string;
}

export interface AutonomousCycleRequest {
  domain?: string;
  max_runs?: number;
}

export interface AutonomousCycleResponse {
  cycle_id: string;
  status: string;
  domain: string;
  max_runs: number;
}

// --- SSE ---

export interface StageProgressEvent {
  stage: string;
  index: number;
  total: number;
  elapsed: number;
}

export interface ProgressDoneEvent {
  done: true;
}

export interface HeartbeatEvent {
  heartbeat: true;
}

export type ProgressEvent = StageProgressEvent | ProgressDoneEvent | HeartbeatEvent;

// --- Ideas ---

export interface IdeaSummary {
  id: number;
  title: string;
  domain: string;
  novelty_score: number | null;
  feasibility_score: number | null;
  overall_score: number | null;
  pipeline_run_id: number | null;
  created_at: string;
}

export interface IdeaDetail extends IdeaSummary {
  problem_statement: string;
  proposed_method: string;
  expected_contributions: string;
  novelty_report: Record<string, unknown> | null;
  feasibility_report: Record<string, unknown> | null;
  proposal_md: string | null;
  proposal_latex: string | null;
  proposal_sections: Record<string, unknown> | null;
}

export interface IdeaListResponse {
  ideas: IdeaSummary[];
  total: number;
  score_guide: Record<string, Record<string, string>>;
}

export interface IdeaFeedbackRequest {
  rating: number;
  notes?: string | null;
}

// --- Gaps ---

export interface ResearchGap {
  id: number;
  title: string;
  description: string;
  gap_type: string;
  confidence: number;
  potential_impact: string;
}

export interface GapListResponse {
  gaps: ResearchGap[];
  total: number;
}

// --- Knowledge ---

export interface KnowledgeSearchResult {
  id: string;
  text: string;
  metadata: Record<string, string>;
  distance: number;
}

export interface KnowledgeSearchResponse {
  query: string;
  results: KnowledgeSearchResult[];
}

// --- Status ---

export interface SystemStatus {
  app_name: string;
  version: string;
  config: Record<string, boolean>;
  defaults: Record<string, number>;
}

